// Approve ORDER token for the proxy contract
const ORDER_TOKEN = "0x4E200fE2f3eFb977d5fd9c430A41531FB04d97B8";
const PROXY_CONTRACT = "0xC8A8Ce0Ab010E499ca57477AC031358febCbbF17";

const orderTokenContract = new ethers.Contract(ORDER_TOKEN, ERC20_ABI, signer);
const approveTx = await orderTokenContract.approve(PROXY_CONTRACT, amount);
await approveTx.wait();

// Fetch the LZ fee
const proxyContract = new ethers.Contract(PROXY_CONTRACT, PROXY_ABI, signer);
const lzFee = await proxyContract.quoteStakeOrder(amount, userAddress);

// The Orderly app multiplies this fee by 1.1 as a buffer
const adjustedLzFee = lzFee * 11n / 10n; // 1.1x multiplier using BigInt

// Stake ORDER tokens
const stakeTx = await proxyContract.stakeOrder(amount, userAddress, {
  value: adjustedLzFee
});
await stakeTx.wait();

console.log("Staking successful:", stakeTx.hash);

