// Example conversion for deposit:
// On-chain amount (18 decimals): 1000000000000000000 (1 USDC)
// Orderly amount (6 decimals): 1000000 (1 USDC)

function toOrderlyAmount(onChainAmount, onChainDecimals, orderlyDecimals) {
  const factor = BigInt(10) ** BigInt(onChainDecimals - orderlyDecimals);
  return onChainAmount / factor;
}

// Example conversion for withdrawal:
// Orderly amount (6 decimals): 1000000 (1 USDC)
// On-chain amount (18 decimals): 1000000000000000000 (1 USDC)

function toOnChainAmount(orderlyAmount, orderlyDecimals, onChainDecimals) {
  const factor = BigInt(10) ** BigInt(onChainDecimals - orderlyDecimals);
  return orderlyAmount * factor;
}

