// Pseudocode for bucketing:
const bucketSize = 100; // $100 intervals
const buckets = {};

positions.forEach(pos => {
  const price = parseFloat(pos.est_liq_price);
  if (!price) return;
  const bucket = Math.floor(price / bucketSize) * bucketSize;
  buckets[bucket] = (buckets[bucket] || 0) + parseFloat(pos.notional);
});

